export const ADMIN_SECTION_ORDER = [
  "MAIN",
  "PUBLIC EXPERIENCE",
  "PLATFORM",
  "MARKETPLACE",
  "PARTNER GROWTH",
  "INSIGHTS",
  "INFRASTRUCTURE",
  "OPERATIONS",
  "ADMINISTRATION",
];

export type AdminNavGroup = { group: string; icon: string; items: AdminPage[]; href: string };
export type AdminNavSection = { section: string; groups: AdminNavGroup[] };

export const ADMIN_NAV: AdminNavSection[] = ADMIN_SECTION_ORDER.map((section) => {
  const groups: AdminNavGroup[] = [];
  for (const p of ADMIN_PAGES) {
    if (p.section !== section) continue;
    let g = groups.find((x) => x.group === p.group);
    if (!g) {
      g = { group: p.group, icon: p.icon, items: [], href: p.href };
      groups.push(g);
    }
    g.items.push(p);
  }
  return { section, groups };
}).filter((s) => s.groups.length > 0);

export const ADMIN_PAGE_BY_HREF = new Map(ADMIN_PAGES.map((p) => [p.href, p]));
export const ADMIN_PAGE_BY_KEY = new Map(ADMIN_PAGES.map((p) => [p.key, p]));

/**
 * Resolve a URL to a page. A trailing segment that does not match a route is
 * treated as a record id, so `<detail route>/<id>` opens that single record.
 */
export function findAdminPage(
  slug: string[] | undefined,
): { page: AdminPage; recordId?: string } | undefined {
  const parts = slug ?? [];
  const exact = ADMIN_PAGE_BY_HREF.get(parts.length ? `/admin/${parts.join("/")}` : "/super");
  if (exact) return { page: exact };
  if (parts.length > 1) {
    const parent = ADMIN_PAGE_BY_HREF.get(`/admin/${parts.slice(0, -1).join("/")}`);
    if (parent) return { page: parent, recordId: parts[parts.length - 1] };
  }
  return undefined;
}

/** The list screen a detail page belongs to, for breadcrumbs and back links. */
export function detailParent(page: AdminPage): AdminPage | undefined {
  return page.detailOf ? ADMIN_PAGE_BY_KEY.get(page.detailOf) : undefined;
}
